use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lefts: Vec<int> = []
    let mut rights: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "insert" || cmd == "contains" || cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            // find node
            let mut cur = root
            let mut par: int = -1
            let mut went_left = false
            while cur != -1 && keys[cur as usize] != x {
                par = cur
                if x < keys[cur as usize] {
                    went_left = true
                    cur = lefts[cur as usize]
                } else {
                    went_left = false
                    cur = rights[cur as usize]
                }
            }
            if cmd == "insert" {
                if cur != -1 {
                    println("dup")
                } else {
                    let id: int = keys.len() as int
                    keys.push(x)
                    lefts.push(-1)
                    rights.push(-1)
                    if par == -1 {
                        root = id
                    } else if went_left {
                        lefts[par as usize] = id
                    } else {
                        rights[par as usize] = id
                    }
                    println("ok")
                }
            } else if cmd == "contains" {
                if cur != -1 { println("yes") } else { println("no") }
            } else {
                if cur == -1 {
                    println("missing")
                } else {
                    let mut target = cur
                    let mut tpar = par
                    let mut tleft = went_left
                    if lefts[cur as usize] != -1 && rights[cur as usize] != -1 {
                        tpar = cur
                        tleft = false
                        target = rights[cur as usize]
                        while lefts[target as usize] != -1 {
                            tpar = target
                            tleft = true
                            target = lefts[target as usize]
                        }
                        keys[cur as usize] = keys[target as usize]
                    }
                    let child = if lefts[target as usize] != -1 { lefts[target as usize] } else { rights[target as usize] }
                    if tpar == -1 {
                        root = child
                    } else if tleft {
                        lefts[tpar as usize] = child
                    } else {
                        rights[tpar as usize] = child
                    }
                    println("ok")
                }
            }
        } else if cmd == "inorder" {
            if root == -1 {
                println("<empty>")
            } else {
                let mut n = root
                while lefts[n as usize] != -1 { n = lefts[n as usize] }
                let mut curk = keys[n as usize]
                let mut out = "${curk}"
                let mut more = true
                while more {
                    let mut c = root
                    let mut found = false
                    let mut best = 0
                    while c != -1 {
                        if keys[c as usize] > curk {
                            found = true
                            best = keys[c as usize]
                            c = lefts[c as usize]
                        } else {
                            c = rights[c as usize]
                        }
                    }
                    if found {
                        out = "${out} ${best}"
                        curk = best
                    } else {
                        more = false
                    }
                }
                println(out)
            }
        } else if cmd == "height" {
            if root == -1 {
                println("0")
            } else {
                let mut queue: Vec<int> = [root]
                let mut depth: Vec<int> = [1]
                let mut head = 0
                let mut best = 0
                while head < queue.len() {
                    let n = queue[head]
                    let d = depth[head]
                    head += 1
                    if d > best { best = d }
                    if lefts[n as usize] != -1 {
                        queue.push(lefts[n as usize])
                        depth.push(d + 1)
                    }
                    if rights[n as usize] != -1 {
                        queue.push(rights[n as usize])
                        depth.push(d + 1)
                    }
                }
                println("${best}")
            }
        } else if cmd == "min" || cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut n = root
                if cmd == "min" {
                    while lefts[n as usize] != -1 { n = lefts[n as usize] }
                } else {
                    while rights[n as usize] != -1 { n = rights[n as usize] }
                }
                println("${keys[n as usize]}")
            }
        }
    }
}

